"""Tests for cynthus.messaging.common.signal.message_base (SignalMessageBase)."""

# Generated by tools/generate_messaging_core_tests.py - edit the generator, not this file.

from datetime import datetime, timezone
from uuid import UUID, uuid4

import pytest
from pydantic import ValidationError

from cynthus.messaging.common.signal.lifecycle_action import LifecycleAction
from cynthus.messaging.common.signal.message_base import SignalMessageBase
from cynthus.messaging.common.signal.part import SignalPart


def values(**overrides):
    return dict(
        event_type='public.meal.plan.created',
        lifecycle_action=LifecycleAction.CREATED,
        correlation_id=uuid4(),
        organization_id=uuid4(),
        workspace_id=uuid4(),
        actor_id=uuid4(),
        **overrides,
    )


def test_is_a_signal_part():
    assert issubclass(SignalMessageBase, SignalPart)


def test_accepts_a_complete_envelope():
    data = values()
    message = SignalMessageBase(**data)

    assert all(getattr(message, name) == value for name, value in data.items())


@pytest.mark.parametrize('field', ['event_type', 'lifecycle_action', 'correlation_id', 'organization_id',
                                   'workspace_id', 'actor_id'])
def test_required_fields(field):
    data = values()
    del data[field]

    with pytest.raises(ValidationError):
        SignalMessageBase(**data)


@pytest.mark.parametrize('field', ['correlation_id', 'organization_id', 'workspace_id', 'actor_id'])
def test_identifiers_must_be_uuids(field):
    with pytest.raises(ValidationError):
        SignalMessageBase(**values(**{}) | {field: 'test-org'})


def test_identifiers_are_parsed_from_strings():
    identifier = uuid4()

    assert SignalMessageBase(**values() | {'actor_id': str(identifier)}).actor_id == identifier


def test_lifecycle_action_is_parsed_from_its_wire_value():
    assert SignalMessageBase(**values() | {'lifecycle_action': 'snapshot'}).lifecycle_action is LifecycleAction.SNAPSHOT


def test_unknown_lifecycle_action_is_rejected():
    with pytest.raises(ValidationError):
        SignalMessageBase(**values() | {'lifecycle_action': 'exploded'})


def test_event_id_defaults_to_a_fresh_uuid():
    first, second = SignalMessageBase(**values()), SignalMessageBase(**values())

    assert isinstance(first.event_id, UUID)
    assert first.event_id != second.event_id


def test_event_id_can_be_supplied():
    identifier = uuid4()

    assert SignalMessageBase(**values() | {'event_id': identifier}).event_id == identifier


def test_timestamp_defaults_to_now_in_utc():
    before = datetime.now(timezone.utc)
    stamp = SignalMessageBase(**values()).timestamp

    assert stamp.tzinfo is not None and stamp.utcoffset().total_seconds() == 0
    assert before <= stamp <= datetime.now(timezone.utc)


def test_message_is_immutable():
    message = SignalMessageBase(**values())

    with pytest.raises(ValidationError):
        message.event_type = 'other'


def test_fields_can_be_supplied_by_name():
    # populate_by_name is enabled on every signal part
    assert SignalMessageBase.model_config['populate_by_name'] is True
